--
-- Name: conversation_room_counts; Type: VIEW; Schema: public; Owner: nouman
--

CREATE VIEW public.conversation_room_counts AS
 SELECT id,
    "projectId",
    ( SELECT count("Comment".id) AS count
           FROM public.comments "Comment"
          WHERE ((("Comment"."relatedTo")::text = 'conversationrooms'::text) AND (("Comment"."relatedId")::text = ("Room".id)::text) AND ("Comment".deleted = '0'::smallint))) AS "commentCount",
    ( SELECT count("Vote".id) AS count
           FROM public.votes "Vote"
          WHERE ((("Vote"."relatedTo")::text = 'conversationrooms'::text) AND (("Vote"."relatedId")::text = ("Room".id)::text) AND ("Vote".vote = '1'::smallint))) AS "likeCount",
    ( SELECT count("Comment".id) AS count
           FROM public.comments "Comment"
          WHERE ((("Room"."roomType")::text = 'vote'::text) AND (("Comment"."relatedTo")::text = 'conversationrooms'::text) AND (("Comment"."relatedId")::text = ("Room".id)::text) AND ("Comment".deleted = '0'::smallint) AND ("Comment".comment = 'I agree'::text))) AS "agreeCount",
    ( SELECT count("Comment".id) AS count
           FROM public.comments "Comment"
          WHERE ((("Room"."roomType")::text = 'vote'::text) AND (("Comment"."relatedTo")::text = 'conversationrooms'::text) AND (("Comment"."relatedId")::text = ("Room".id)::text) AND ("Comment".deleted = '0'::smallint) AND ("Comment".comment = 'I disagree'::text))) AS "disagreeCount",
    ( SELECT max("Comment"."dateCreated") AS max
           FROM public.comments "Comment"
          WHERE ((("Comment"."relatedTo")::text = 'conversationrooms'::text) AND (("Comment"."relatedId")::text = ("Room".id)::text) AND ("Comment".deleted = '0'::smallint))) AS "lastCommentDate"
   FROM public.conversation_rooms "Room"
  WHERE (deleted = '0'::smallint);


ALTER VIEW public.conversation_room_counts OWNER TO nouman;

