3dddb2716adc-6735-a2f4-c7d3cad73173	Normalize invalid plan issue entries in decodePlanBody.	2026-10-24 07:03:25	2026-10-24 07:30:34	0	<p><span class="colour" style="color: rgb(145, 152, 161);" data-tomark-pass="">A loaded plan with&nbsp;</span><code data-backticks="1">issues: [null]</code><span class="colour" style="color: rgb(145, 152, 161);" data-tomark-pass="">&nbsp;reaches&nbsp;</span><code data-backticks="1">Idea::PlanBox</code><span class="colour" style="color: rgb(145, 152, 161);" data-tomark-pass="">, which reads&nbsp;</span><code data-backticks="1">issue.key</code><span class="colour" style="color: rgb(145, 152, 161);" data-tomark-pass="">&nbsp;while mapping the array and throws. The same entry can make&nbsp;</span><code data-backticks="1">Idea::CreatedIssuesBox</code><span class="colour" style="color: rgb(145, 152, 161);" data-tomark-pass="">&nbsp;throw when a created issue is missing because its fallback reads&nbsp;</span><code data-backticks="1">candidate.key</code><span class="colour" style="color: rgb(145, 152, 161);" data-tomark-pass="">. Normalize invalid entries once in&nbsp;</span><code data-backticks="1">decodePlanBody</code><span class="colour" style="color: rgb(145, 152, 161);" data-tomark-pass="">&nbsp;so both consumers receive valid issue objects.<br>\n</span>export default function decodePlanBody(body) {<br>\n&nbsp;&nbsp;&nbsp;&nbsp; if (typeof body === 'string') {<br>\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; try {<br>\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; body = JSON.parse(body);<br>\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; } catch (error) {<br>\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; body = { summary: body };<br>\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; }<br>\n&nbsp;&nbsp;&nbsp;&nbsp; }<br>\n-&nbsp;&nbsp;&nbsp; return body &amp;&amp; typeof body === 'object' ? body : {};<br>\n+&nbsp;&nbsp;&nbsp; if (body &amp;&amp; typeof body === 'object' &amp;&amp; Array.isArray(body.issues)) {<br>\n+&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; return {<br>\n+&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; ...body,<br>\n+&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; issues: body.issues.filter(issue =&gt; issue &amp;&amp; typeof issue === 'object')<br>\n+&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; };<br>\n+&nbsp;&nbsp;&nbsp; }<br>\n+&nbsp;&nbsp;&nbsp; return body &amp;&amp; typeof body === 'object' ? body : {};<br>\n}<span class="colour" style="color: rgb(145, 152, 161);" data-tomark-pass=""></span></p>\n	1	1	1	1	1	4109	2026-11-20	2026-10-24	done	medium	add12ff55acb-1902-6b9c-30d5411f7729	ac6af3216ad8-d753-535b-b21c3700739d	cad135f26adc-e07b-a0a9-8a51ae1aaf9d	ae6454575acb-1902-6b9c-f2ffa11a2697	Hammad Hassan	Hammad Hassan	07cf00426adc-9973-8304-925b9504afef	402f48b562c6-8e43-a8e0-0abdb1b2f5be	2026-10-24 07:30:34	aprom	0	0
